import React, { useState } from 'react';
import { downloadDeptReport } from '../utils/pdfReports';

function AddDeptModal({ open, onClose, onAdd }) {
  const [name, setName] = useState('');
  const [err, setErr] = useState('');

  const handleAdd = () => {
    if (!name.trim()) { setErr('Department name is required'); return; }
    onAdd(name.trim()); setName(''); setErr(''); onClose();
  };

  if (!open) return null;
  return (
    <div className="modal-overlay open" onClick={e => e.target === e.currentTarget && onClose()}>
      <div className="modal modal-md">
        <div className="modal-header">
          <div><div className="modal-title">Add Department</div><div className="modal-subtitle">Create a new department</div></div>
          <button className="modal-close" onClick={onClose}><i className="fas fa-times"></i></button>
        </div>
        <div className="modal-body">
          <div className="form-group">
            <label className="form-label">Department Name <span className="req-star">*</span></label>
            <div className="input-wrapper">
              <i className="fas fa-building input-icon"></i>
              <input className={`form-input has-icon${err ? ' error-field' : ''}`} placeholder="e.g. Administration, Academics..." value={name}
                onChange={e => { setName(e.target.value); setErr(''); }}
                onKeyDown={e => e.key === 'Enter' && handleAdd()} autoFocus />
            </div>
            {err && <span className="field-msg error"><i className="fas fa-times-circle"></i> {err}</span>}
          </div>
          <div className="modal-footer">
            <button className="btn btn-secondary btn-md" onClick={onClose}>Cancel</button>
            <button className="btn btn-primary btn-md" onClick={handleAdd}><i className="fas fa-plus"></i> Add Department</button>
          </div>
        </div>
      </div>
    </div>
  );
}

function AddDesigModal({ open, dept, onClose, onAdd }) {
  const [name, setName] = useState('');
  const [qual, setQual] = useState('');
  const [job, setJob] = useState('');
  const [err, setErr] = useState('');

  const handleAdd = () => {
    if (!name.trim()) { setErr('Designation name is required'); return; }
    onAdd(dept.id, { name: name.trim(), qual: qual.trim(), job: job.trim() });
    setName(''); setQual(''); setJob(''); setErr(''); onClose();
  };

  if (!open || !dept) return null;
  return (
    <div className="modal-overlay open" onClick={e => e.target === e.currentTarget && onClose()}>
      <div className="modal modal-md">
        <div className="modal-header">
          <div><div className="modal-title">Add Designation</div><div className="modal-subtitle">For department: {dept.name}</div></div>
          <button className="modal-close" onClick={onClose}><i className="fas fa-times"></i></button>
        </div>
        <div className="modal-body">
          <div className="form-grid" style={{ gap: 14 }}>
            <div className="form-group">
              <label className="form-label">Designation Title <span className="req-star">*</span></label>
              <input className={`form-input${err ? ' error-field' : ''}`} placeholder="e.g. Principal, Teacher Math..." value={name}
                onChange={e => { setName(e.target.value); setErr(''); }} autoFocus />
              {err && <span className="field-msg error"><i className="fas fa-times-circle"></i> {err}</span>}
            </div>
            <div className="form-group">
              <label className="form-label">Qualification</label>
              <input className="form-input" placeholder="e.g. PhD, Masters, BA..." value={qual} onChange={e => setQual(e.target.value)} />
            </div>
            <div className="form-group">
              <label className="form-label">Job Description</label>
              <input className="form-input" placeholder="Brief role description..." value={job} onChange={e => setJob(e.target.value)} />
            </div>
          </div>
          <div className="modal-footer">
            <button className="btn btn-secondary btn-md" onClick={onClose}>Cancel</button>
            <button className="btn btn-primary btn-md" onClick={handleAdd}><i className="fas fa-plus"></i> Add Designation</button>
          </div>
        </div>
      </div>
    </div>
  );
}

