const thStyle = {
  fontSize: 11,
  fontWeight: 700,
  letterSpacing: '.5px',
  textTransform: 'uppercase',
  color: 'var(--text-muted)',
};

const pageBtnStyle = {
  width: 32,
  height: 32,
  border: '1px solid var(--border-light)',
  borderRadius: 8,
  background: 'transparent',
  cursor: 'pointer',
  color: 'var(--text-secondary)',
  fontSize: 13,
  display: 'inline-flex',
  alignItems: 'center',
  justifyContent: 'center',
};
export default function DepartmentsTab({ deptsData, setDeptsData, schoolInfo, showToast, showSuccess }) {
  const [search, setSearch] = useState('');
  const [expandedId, setExpandedId] = useState(null);
  const [showAddDept, setShowAddDept] = useState(false);
  const [desigTarget, setDesigTarget] = useState(null);
  const [deleteTarget, setDeleteTarget] = useState(null);

  const [editDesigTarget, setEditDesigTarget] = useState(null); // { deptId, idx }
  const [editDesigForm, setEditDesigForm] = useState({ name: '', qual: '', job: '' });

  const handleEditDesig = (deptId, idx) => {
    const dept = deptsData.find(d => d.id === deptId);
    const d = dept?.designations[idx];
    if (!d) return;
    setEditDesigTarget({ deptId, idx });
    setEditDesigForm({ name: d.name, qual: d.qual || '', job: d.job || '' });
  };

  const saveDesigEdit = () => {
    if (!editDesigForm.name.trim()) return;
    setDeptsData(prev => prev.map(d => {
      if (d.id !== editDesigTarget.deptId) return d;
      const desigs = [...d.designations];
      desigs[editDesigTarget.idx] = { ...editDesigForm, name: editDesigForm.name.trim() };
      return { ...d, designations: desigs };
    }));
    showToast('Designation updated', 'success');
    setEditDesigTarget(null);
  };
  const filtered = search ? deptsData.filter(d => d.name.toLowerCase().includes(search.toLowerCase())) : deptsData;
  const totalPosts = deptsData.reduce((s, d) => s + d.designations.length, 0);

  const handleAddDept = (name) => {
    setDeptsData(prev => [...prev, { id: Date.now(), name, designations: [] }]);
    showToast(`Department "${name}" added`, 'success');
  };

  const handleAddDesig = (deptId, desig) => {
    setDeptsData(prev => prev.map(d => d.id === deptId ? { ...d, designations: [...d.designations, desig] } : d));
    showToast('Designation added', 'success');
  };

  const handleDeleteDesig = (deptId, idx) => {
    setDeptsData(prev => prev.map(d => d.id === deptId ? { ...d, designations: d.designations.filter((_, i) => i !== idx) } : d));
    showToast('Designation removed', 'info');
  };

  const handleDeleteDept = (id) => {
    const dept = deptsData.find(d => d.id === id);
    setDeptsData(prev => prev.filter(d => d.id !== id));
    if (expandedId === id) setExpandedId(null);
    setDeleteTarget(null);
    showToast(`"${dept?.name}" deleted`, 'info');
  };

  return (
    <div className="tab-panel active">
      {/* Toolbar */}
      <div className="classes-toolbar" style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 12, flexWrap: 'wrap', marginBottom: 14 }}>
        <div className="toolbar-left" style={{ display: 'flex', alignItems: 'center', gap: 14, flexWrap: 'wrap' }}>
          <div className="search-box" style={{ minWidth: 240 }}>
            <i className="fas fa-search"></i>
            <input placeholder="Search departments..." value={search} onChange={e => setSearch(e.target.value)} />
          </div>
        </div>
        <div className="toolbar-right" style={{ display: 'flex', gap: 10, flexWrap: 'wrap' }}>
          <button className="btn btn-pdf btn-md" onClick={() => downloadDeptReport(deptsData, schoolInfo || {}, showToast)}>
            <i className="fas fa-file-pdf"></i> Download Report
          </button>
          <button className="btn btn-primary btn-md" onClick={() => setShowAddDept(true)}>
            <i className="fas fa-plus"></i> Add New Department
          </button>
        </div>
      </div>

      {/* Table */}
      <div className="classes-table-card" style={{ overflowX: 'auto' }}>
        <div
          className="dept-table-head"
          style={{
            display: 'grid',
            gridTemplateColumns: '60px 1fr 220px 120px',
            alignItems: 'center',
            padding: '14px 20px',
            background: 'var(--bg-subtle, #f8fafc)',
            borderBottom: '1px solid var(--border-light)',
            minWidth: 640,
          }}
        >
          <div className="th" style={thStyle}>#</div>
          <div className="th" style={thStyle}>Department</div>
          <div className="th" style={{ ...thStyle, textAlign: 'center' }}>Designation</div>
          <div className="th" style={{ ...thStyle, textAlign: 'center' }}>Details</div>
        </div>

        <div>
          {!filtered.length ? (
            <div className="empty-state">
              <div className="empty-icon"><i className="fas fa-building"></i></div>
              <div className="empty-title">No Departments Yet</div>
              <div className="empty-sub">Add your first department to get started.</div>
              <button className="btn btn-primary btn-md" onClick={() => setShowAddDept(true)}><i className="fas fa-plus"></i> Add Department</button>
            </div>
          ) : filtered.map((dept, i) => {
            const exp = expandedId === dept.id;
            const postCount = dept.designations.length;
            return (
              <div key={dept.id} style={{ borderBottom: '1px solid var(--border-light)', minWidth: 640 }}>
                {/* Main row */}
                <div
                  className={`dept-row${exp ? ' expanded-row' : ''}`}
                  style={{
                    display: 'grid',
                    gridTemplateColumns: '60px 1fr 220px 120px',
                    alignItems: 'center',
                    padding: '16px 20px',
                    cursor: 'pointer',
                    background: exp ? 'var(--bg-base, #f9fbff)' : 'transparent',
                  }}
                  onClick={() => setExpandedId(exp ? null : dept.id)}
                >
                  {/* # box */}
                  <div className="td">
                    <span
                      style={{
                        display: 'inline-flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        width: 30,
                        height: 30,
                        border: '1px solid var(--border-light)',
                        borderRadius: 8,
                        fontSize: 13,
                        fontWeight: 600,
                        color: 'var(--text-secondary)',
                      }}
                    >
                      {i + 1}
                    </span>
                  </div>

                  {/* Department pill */}
                  <div className="td">
                    <span
                      className="dept-pill"
                      style={{
                        display: 'inline-flex',
                        alignItems: 'center',
                        gap: 8,
                        padding: '8px 14px',
                        background: 'rgba(30,58,138,.08)',
                        color: 'var(--brand-primary)',
                        borderRadius: 10,
                        fontSize: 14,
                        fontWeight: 600,
                      }}
                    >
                      <i className="fas fa-building" style={{ fontSize: 12 }}></i>{dept.name}
                    </span>
                  </div>

                  {/* Designation column: + button + post count */}
                  <div className="td" style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 12 }}>
                    <button
                      className="btn btn-primary btn-sm"
                      onClick={e => { e.stopPropagation(); setDesigTarget(dept); }}
                      style={{ whiteSpace: 'nowrap' }}
                    >
                      <i className="fas fa-plus"></i> Designation
                    </button>
                    {postCount > 0 && (
                      <span style={{ fontSize: 13, color: 'var(--text-muted)', whiteSpace: 'nowrap' }}>
                        {postCount} post{postCount !== 1 ? 's' : ''}
                      </span>
                    )}
                  </div>

                  {/* Details column: trash + chevron */}
                  <div className="td" style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8 }}>
                    <button
                      className="btn btn-icon btn-danger btn-sm"
                      onClick={e => { e.stopPropagation(); setDeleteTarget(dept); }}
                    >
                      <i className="fas fa-trash"></i>
                    </button>
                    <button
                      className={`expand-btn${exp ? ' open' : ''}`}
                      onClick={e => { e.stopPropagation(); setExpandedId(exp ? null : dept.id); }}
                      style={{
                        width: 32,
                        height: 32,
                        border: '1px solid var(--border-light)',
                        borderRadius: 8,
                        background: 'transparent',
                        cursor: 'pointer',
                        color: 'var(--text-secondary)',
                        transition: 'transform .2s',
                        transform: exp ? 'rotate(180deg)' : 'none',
                      }}
                    >
                      <i className="fas fa-chevron-down"></i>
                    </button>
                  </div>
                </div>

                {/* Expanded designations */}
                {exp && (
                  <div style={{ background: 'var(--bg-base)', borderTop: '1px solid var(--border-light)' }}>
                    <div style={{ padding: '12px 20px 4px', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                      <span style={{ fontSize: 12, fontWeight: 700, color: 'var(--brand-primary)' }}>
                        <i className="fas fa-id-badge" style={{ marginRight: 6 }}></i>{dept.name} — Designations
                      </span>
                      <button className="btn btn-ghost btn-sm" onClick={() => setDesigTarget(dept)}>
                        <i className="fas fa-plus"></i> Add
                      </button>
                    </div>
                    <div className="desig-list" style={{ padding: '4px 20px 16px' }}>
                      {!postCount ? (
                        <div className="empty-mini"><i className="fas fa-id-badge"></i>No designations yet</div>
                      ) : dept.designations.map((d, di) => (
                        <div key={di} className="desig-item">
                          <div>
                            <div className="desig-name">{d.name}</div>
                            {d.qual && <span className="desig-qual">{d.qual}</span>}
                            {d.job && <div style={{ fontSize: 11, color: 'var(--text-muted)', marginTop: 2, fontStyle: 'italic' }}>{d.job}</div>}
                          </div>
                          <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                            <span className="desig-num">#{String(di + 1).padStart(2, '0')}</span>
                            <button className="btn btn-icon btn-ghost btn-sm" title="Edit designation" onClick={() => handleEditDesig(dept.id, di)}>
                              <i className="fas fa-pen"></i>
                            </button>
                            <button className="btn btn-icon btn-danger btn-sm" onClick={() => handleDeleteDesig(dept.id, di)}>
                              <i className="fas fa-times"></i>
                            </button>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>

        {/* Pagination */}
        <div className="pagination" style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '14px 20px', flexWrap: 'wrap', gap: 10 }}>
          <div className="pagination-info">Showing <strong>{filtered.length}</strong> of <strong>{deptsData.length}</strong> departments</div>
          <div style={{ display: 'flex', gap: 6 }}>
            <button className="page-btn" style={pageBtnStyle}><i className="fas fa-chevron-left"></i></button>
            <button className="page-btn active" style={{ ...pageBtnStyle, background: 'var(--brand-primary)', color: '#fff', borderColor: 'var(--brand-primary)' }}>1</button>
            <button className="page-btn" style={pageBtnStyle}><i className="fas fa-chevron-right"></i></button>
          </div>
        </div>
      </div>

      <AddDeptModal open={showAddDept} onClose={() => setShowAddDept(false)} onAdd={handleAddDept} />
      <AddDesigModal open={!!desigTarget} dept={desigTarget} onClose={() => setDesigTarget(null)} onAdd={handleAddDesig} />

      {/* Edit Designation Modal */}
      {editDesigTarget && (
        <div className="modal-overlay open" onClick={e => e.target === e.currentTarget && setEditDesigTarget(null)}>
          <div className="modal modal-md">
            <div className="modal-header">
              <div><div className="modal-title">Edit Designation</div><div className="modal-subtitle">Update designation details</div></div>
              <button className="modal-close" onClick={() => setEditDesigTarget(null)}><i className="fas fa-times"></i></button>
            </div>
            <div className="modal-body">
              <div className="form-grid" style={{ gap: 14 }}>
                <div className="form-group">
                  <label className="form-label">Designation Title <span className="req-star">*</span></label>
                  <input className="form-input" value={editDesigForm.name} onChange={e => setEditDesigForm(f => ({ ...f, name: e.target.value }))} autoFocus />
                </div>
                <div className="form-group">
                  <label className="form-label">Qualification</label>
                  <input className="form-input" value={editDesigForm.qual} onChange={e => setEditDesigForm(f => ({ ...f, qual: e.target.value }))} />
                </div>
                <div className="form-group">
                  <label className="form-label">Job Description</label>
                  <input className="form-input" value={editDesigForm.job} onChange={e => setEditDesigForm(f => ({ ...f, job: e.target.value }))} />
                </div>
              </div>
              <div className="modal-footer">
                <button className="btn btn-secondary btn-md" onClick={() => setEditDesigTarget(null)}>Cancel</button>
                <button className="btn btn-primary btn-md" onClick={saveDesigEdit}><i className="fas fa-save"></i> Save Changes</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {deleteTarget && (
        <div className="modal-overlay open" onClick={e => e.target === e.currentTarget && setDeleteTarget(null)}>
          <div className="modal modal-sm">
            <div className="modal-header">
              <div className="modal-title" style={{ color: 'var(--error)' }}><i className="fas fa-exclamation-triangle" style={{ marginRight: 7 }}></i>Delete Department</div>
              <button className="modal-close" onClick={() => setDeleteTarget(null)}><i className="fas fa-times"></i></button>
            </div>
            <div className="modal-body">
              <p style={{ fontSize: 13.5, color: 'var(--text-secondary)', lineHeight: 1.7, marginBottom: 20 }}>
                Delete <strong>"{deleteTarget.name}"</strong>? This will also remove all {deleteTarget.designations.length} designations.
              </p>
              <div className="modal-footer">
                <button className="btn btn-secondary btn-md" onClick={() => setDeleteTarget(null)}>Cancel</button>
                <button className="btn btn-danger btn-md" onClick={() => handleDeleteDept(deleteTarget.id)}><i className="fas fa-trash"></i> Delete</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
